+
+  if (document.hidden) store.setVisible(false);
+  tick(true);
+  store.start();
+  if (!document.hidden) schedule();
+
+  return {
+    store,
+    render: () => tick(true),
+    setNow(fn: (() => number) | null) { nowFn = fn || (() => Date.now()); tick(true); }
+  };
+}
